import sqlite3

def migrate(path, fault=None):
    c=sqlite3.connect(path)
    try:
        c.execute('BEGIN IMMEDIATE')
        version=c.execute('PRAGMA user_version').fetchone()[0]
        if version>1:
            raise ValueError('unsupported version')
        if version==1:
            c.rollback()
            return
        exists=c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='items'").fetchone()
        c.execute('CREATE TABLE items_new(id INTEGER PRIMARY KEY,value TEXT NOT NULL,normalized TEXT NOT NULL)')
        if exists:
            rows=c.execute('SELECT id,value FROM items').fetchall()
            c.executemany('INSERT INTO items_new VALUES(?,?,?)',[(i,v,v.strip().lower()) for i,v in rows])
        if fault:
            fault('after_copy')
        if exists:
            c.execute('DROP TABLE items')
        c.execute('ALTER TABLE items_new RENAME TO items')
        c.execute('PRAGMA user_version=1')
        if fault:
            fault('before_commit')
        c.commit()
    except BaseException:
        c.rollback()
        raise
    finally:
        c.close()

def read_items(path):
    c=sqlite3.connect(path)
    try:
        return c.execute('SELECT id,normalized FROM items ORDER BY id').fetchall()
    finally:
        c.close()

