    def test_hooks_in_order(self):
        self.legacy();calls=[];migrate(self.p,calls.append);self.assertEqual(calls,['after_copy','before_commit'])
    def test_future_version_unchanged(self):
        self.legacy()
        with sqlite3.connect(self.p) as c:c.execute('PRAGMA user_version=7')
        before=self.state()
        with self.assertRaises(ValueError):migrate(self.p)
