    def test_ordered_delivery_failure_preserves_previous_ack(self):
        for id in ('c','a','b'):
            self.add(id,id+'-payload')
            leased=claim(self.p,0,10)
            self.assertEqual(leased[0],id)
            self.assertTrue(complete(self.p,id,leased[2],id+'-result',1))
        observed=[]
        def delivery(id,body):
            observed.append((id,body))
            if id=='b':raise RuntimeError('second event fails')
        with self.assertRaisesRegex(RuntimeError,'second event fails'):
            publish(self.p,delivery)
        self.assertEqual(observed,[('a','a-result'),('b','b-result')])
        init(self.p)
        with sqlite3.connect(self.p) as c:
            self.assertEqual(c.execute('SELECT id,delivered FROM outbox ORDER BY id').fetchall(),[('a',1),('b',0),('c',0)])
        replay=[]
        self.assertEqual(publish(self.p,lambda id,body:replay.append((id,body))),2)
        self.assertEqual(replay,[('b','b-result'),('c','c-result')])
        self.assertEqual(publish(self.p,lambda *args:self.fail('already delivered')),0)
